shots.draw_js:
clearScene();setBig(null);
setEq("$$V^{\\pi}(s)\\;=\\;\\mathbb{E}_{\\pi}\\big[\\,r_t+\\gamma r_{t+1}+\\gamma^2 r_{t+2}+\\cdots \\mid s_t=s\\,\\big]$$","top");
mdpChain({n:4,y:320,r:30,x:400,gap:160,
  label:function(i){return "s"+(i+3);},
  cls:function(i){return i===1?"v":"";},
  arcs:[[1,2,"→ 右","g",0],[1,0,"← 左","r",-84]]});
setCap("MDP = MRP + 动作：每个状态不再只有一条出边。<b>那 MRP 那三把工具是不是要重造？</b>");

clearScene();setEq(null);
setBig("策略评估需要新算法","MDP 多了一整个维度，得重造工具");
setCap("这个模型不荒谬：多一个维度，<b>通常确实</b>意味着要换方法。");

clearScene();setBig(null);
setEq("$$R^{\\pi}(s)=\\sum_a \\pi(a\\mid s)R(s,a) \\qquad P^{\\pi}(s'\\mid s)=\\sum_a \\pi(a\\mid s)P(s'\\mid s,a)$$","top");
lamps({y:320,gap:340,items:[
  {label:"固定一个 π",sub:"动作维被求和掉",state:"on"},
  {label:"剩下的",sub:"就是一个 MRP",state:"on"}]});
setCap("于是 V^π(MDP) = V(诱导出的 MRP)。<b>披露</b>：约 00:32:36 口头说成「显然的求平均」，两个等式都没写在板上。");

clearScene();setBig(null);
setEq("$$\\pi_{\\text{left}}:\\ \\text{每格都向左}\\qquad\\Longrightarrow\\qquad V^{\\pi_{\\text{left}}}=(I-\\gamma P^{\\pi})^{-1}R^{\\pi}$$","top");
bars({vals:[10.00,8.18,6.69,5.48,4.48,3.67,21.18],
  x:210,y:430,w:860,h:170,max:100,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===0?"y":"r";},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>π = 一直向左</b>：V(s₁)=10=1/(1−0.9)，卡在 s₁ 永远只吃那个 +1。完全合法、精确可评估、但很糟。");

clearScene();setBig(null);
setEq("$$\\pi_{\\text{left}}\\ \\longrightarrow\\ \\pi_{\\text{right}}\\quad\\text{同一个 MDP，换一个 }\\pi\\text{，换一个 MRP}$$","top");
morphBars({from:[10.00,8.18,6.69,5.48,4.48,3.67,21.18],
  to:[31.82,36.67,44.81,54.77,66.94,81.82,100.00],
  x:210,y:430,w:860,h:170,max:100,dur:1600,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===6?"g":"b";},
  fmt:function(v){return v.toFixed(2);}});
setCap("π 不是在 MDP 里「挑一条路」，<b>π 是在挑一个 MRP</b> —— 于是换一条完全不同的值曲线。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:300,items:[
  {label:"MDP + 固定 π",sub:"求和掉动作维",state:"on"},
  {label:"得到 MRP",sub:"R^π · P^π",state:"on"},
  {label:"三把工具",sub:"原样可用",state:"on"}]});
setCap("<b>指名反驳</b>：这是恒等变换，不是新问题。代价也照搬 —— <b>迭代每轮仍是 |S|²</b>，到值迭代才变 |S|²|A|。");

clearScene();setBig(null);setEq(null);
gridworld({rows:1,cols:7,cs:110,y:260,
  tag:function(i,j){return "s"+(j+1);},
  pol:function(){return "r";},
  cls:function(){return "b";}});
note("7 个状态，每格 2 个动作",640,430,"sm");
setCap("确定性策略 = 给每个状态指定一个动作。<b>这样的策略一共有多少个？</b>");

clearScene();setEq(null);
setBig("7 × 2 = 14 个","或者：|S|^|A| = 7² = 49 个");
setCap("两个错法：一个把它当成<b>线性</b>，一个把<b>底数和指数写反了</b>。");

clearScene();setBig(null);
setEq("$$|\\Pi_{\\text{det}}|\\;=\\;|A|^{|S|}$$","top");
tree({r:22,nodes:[
  {id:"root",x:640,y:238,label:"",sub:"起点"},
  {id:"a",parent:"root",x:440,y:326,label:"←",sub:"s₁ 选左"},
  {id:"b",parent:"root",x:840,y:326,label:"→",sub:"s₁ 选右"},
  {id:"aa",parent:"a",x:340,y:424,label:"←",cls:"g"},
  {id:"ab",parent:"a",x:540,y:424,label:"→",cls:"g"},
  {id:"ba",parent:"b",x:740,y:424,label:"←",cls:"g"},
  {id:"bb",parent:"b",x:940,y:424,label:"→",cls:"g"}]});
setCap("每个状态<b>独立</b>选一次，所以每加一个状态叶子数就<b>乘以</b> |A|：两状态两动作 → 4 个叶子。");

clearScene();setBig(null);
setEq("$$7\\text{ 个状态}\\quad 2\\text{ 个动作}$$","top");
fillBars({vals:[14,49,128],order:[0,1,2],step:620,
  x:300,y:430,w:680,h:170,max:128,
  label:function(i){return ["|S|·|A|","|S|^|A|","|A|^|S|"][i];},
  cls:function(i){return i===2?"g":"r";},
  fmt:function(v){return v.toFixed(0);}});
setCap("<b>128</b>。线性猜测差了 9 倍，底数写反差了 2.6 倍 —— 差的是量级，不是零头。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"策略迭代必终止",sub:"本例只用 6 轮",state:"on"},
  {label:"最优就在这 128 个里",sub:"确定性且平稳",state:"on"}]});
setCap("指数、但<b>有限</b>。<b>披露</b>：第二条讲座只给了直觉（「无限长的未来每时刻看起来都一样」），没有证明。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:260,items:[
  {label:"|S|·|A| = 14",sub:"数的是 (s,a) 对",state:"dead"},
  {label:"|S|^|A| = 49",sub:"底数指数写反",state:"dead"},
  {label:"|A|^|S| = 128",sub:"每状态独立选",state:"on"},
  {label:"有限",sub:"策略迭代必终止",state:"on"}]});
setCap("<b>指名反驳</b>：判别口诀 —— <b>指数上是「独立做选择的次数」</b>。有限时域下这条不成立（L1 KP9）。");

clearScene();setBig(null);
setEq("$$\\pi_{i+1}(s)\\;=\\;\\arg\\max_a\\; Q^{\\pi_i}(s,a)$$","top");
note("Q 的上标是 π_i",640,320,"y lg");
note("只有第 1 步换了动作",640,380,"r lg");
setCap("第 1 步用新动作，<b>第 2 步往后全是旧策略</b> —— 凭什么由此断定整条未来都更好？她自己说：「这里有点怪」。");

clearScene();setEq(null);
setBig("贪心只保证第一步更好","第一步贪一口，后面说不定亏更多");
setCap("这个顾虑不是杞人忧天 —— 最短路、背包、特征选择里，<b>贪心确实会栽在这上面</b>。");

clearScene();setBig(null);setEq(null);
flip(T("v1","V<sup>π₁</sup>(s)")+T("le1","&nbsp;=&nbsp;")+T("q1","Q<sup>π₁</sup>(s, π₁(s))")+T("le2","&nbsp;≤&nbsp;")+T("mx","max<sub>a</sub> Q<sup>π₁</sup>(s,a)","hl"));
note("π₁ 旧 · π₂ 新",640,420,"sm lg");
setCap("<b>动作一</b>：π₁(s) 只是众多 a 中的一个，取 max 不会更小。平凡，但<b>承重</b>。");

clearScene();setBig(null);setEq(null);
flip(T("v1","V<sup>π₁</sup>(s)")+T("le2","&nbsp;≤&nbsp;")+T("q2","Q<sup>π₁</sup>(s, π₂(s))","hl")+T("eq3","&nbsp;=&nbsp;")+T("r2","r(s, π₂(s))")+T("pl","&nbsp;+&nbsp;γ&nbsp;")+T("sum","Σ<sub>s′</sub> P(s′|s, π₂(s))")+T("vin","V<sup>π₁</sup>(s′)","hl"));
note("盯住右端那个 V^π₁(s′)",640,420,"g lg");
setCap("<b>动作二</b>：max 改写成 π₂ 的定义，再展开一层 Bellman。<b>第 1 步已经换成 π₂ 了。</b>");

clearScene();setBig(null);setEq(null);
flip(T("v1","V<sup>π₁</sup>(s)")+T("le2","&nbsp;≤&nbsp;")+T("r2","r(s, π₂(s))")+T("pl","&nbsp;+&nbsp;γ&nbsp;")+T("sum","Σ<sub>s′</sub> P(s′|s, π₂(s))")+T("br1","[&nbsp;")+T("r3","r(s′, π₂(s′))","hl")+T("pl2","&nbsp;+&nbsp;γ&nbsp;")+T("sum2","Σ<sub>s″</sub> P(s″|s′, π₂(s′))","hl")+T("vin2","V<sup>π₁</sup>(s″)")+T("br2","&nbsp;]"));
note("每代一次锁死一步",640,292,"g lg");
setCap("<b>再代一次</b>：第 2 步也变成 π₂。展开 k 次 ⟹ 前 k 步全是 π₂，尾项 γ^k·V^π₁，而 |V^π₁| ≤ R_max/(1−γ) 有界。");

clearScene();setBig(null);setEq(null);
flip(T("v1","V<sup>π₁</sup>(s)")+T("le2","&nbsp;≤&nbsp;")+T("lim","lim<sub>k→∞</sub>&nbsp;")+T("allpi2","E<sub>π₂</sub>[ r₀ + γr₁ + γ²r₂ + ⋯ + γ<sup>k−1</sup>r<sub>k−1</sub> ]","hl")+T("tail","&nbsp;+&nbsp;γ<sup>k</sup>V<sup>π₁</sup>")+T("arr","&nbsp;&nbsp;⟶&nbsp;&nbsp;")+T("v2","V<sup>π₂</sup>(s)","res"));
note("尾项 → 0",640,420,"g lg");
setCap("<b>极限</b>：右边正是 V^π₂(s)。于是 <b>V^π₁ ≤ V^π₂ 逐状态成立</b>；π₁ 非最优时至少一处严格小于。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:250,items:[
  {label:"代 1 次",sub:"第 1 步 = π₂",state:"on"},
  {label:"代 2 次",sub:"前 2 步 = π₂",state:"on"},
  {label:"代 k 次",sub:"前 k 步 = π₂",state:"on"},
  {label:"k → ∞",sub:"整条 = π₂",state:"on"}]});
setCap("<b>指名反驳</b>：贪心只改一步 —— 但这一步可以被<b>代入无穷多次</b>。承重前提：γ < 1 且奖励有界。");
